// Assembles field_simd.wat into field_simd.wasm.js (a base64 string the core loads). Developer step only: needs `npm i wabt`;
// the generated file is committed, so building the pages or running the tests does not need wabt.
const fs = require('fs'), path = require('path');
require('wabt')().then(wabt => {
  const mod = wabt.parseWat('field_simd.wat', fs.readFileSync(path.join(__dirname, 'field_simd.wat'), 'utf8'), { simd: true });
  const { buffer } = mod.toBinary({ log: false });
  const b64 = Buffer.from(buffer).toString('base64');
  fs.writeFileSync(path.join(__dirname, 'field_simd.wasm.js'), `// GENERATED by build_wasm.js from field_simd.wat\nglobalThis.POTENTIA_FIELD_SIMD_B64 = '${b64}';\n`);
  console.log('wrote field_simd.wasm.js,', buffer.length, 'bytes of WebAssembly');
});
